97:         public async Task<PlayerIdentity> CreatePlayerIdentityAsync(string? impressionId = null)
98:         {
99:             string? idfa = null;
100:             string? idfv = null;
101:             string? gaid = null;
102:             string? appInstanceId = null;
103:             string? firebaseSessionId = null;
104:             string? firebaseAppId = null;
105:             bool adsIntentGranted = false;
106: 
107: #if ENABLE_UNITY_CONSENT
108:             if (ConsentState.AdsIntent == ConsentStatus.Granted)
109:             {
110:                 adsIntentGranted = true;
111:             }
112: #endif
113: 
114:             switch (Application.platform)
115:             {
116:                 case RuntimePlatform.Android:
117:                     if (adsIntentGranted)
118:                     {
119:                         var enabledAttributes = EnabledAttributes;
120:                         if (enabledAttributes.Contains(ConnectionsSettingsClient.GaidKey))
121:                         {
