123:                             gaid = await m_AdvertisingIdClient.FetchGaidAsync();
124:                         }
125:                         m_FirebaseAnalyticsClient ??= new FirebaseAnalyticsClient();
126:                         (appInstanceId, firebaseSessionId, firebaseAppId) = await FetchEnabledFirebaseIdsAsync(m_FirebaseAnalyticsClient);
127:                     }
128:                     break;
129:                 case RuntimePlatform.IPhonePlayer:
130:                 case RuntimePlatform.OSXPlayer:
131:                 case RuntimePlatform.tvOS:
132: #if UNITY_VISIONOS
133:             case RuntimePlatform.VisionOS:
134: #endif
135:                     m_NativeStore ??= new NativeStoreProvider().GetStorekit();
136:                     if (adsIntentGranted && EnabledAttributes.Contains(ConnectionsSettingsClient.IdfaKey))
137:                     {
138:                         idfa = m_NativeStore.FetchAdvertisingIdentifier();
139:                     }
140: 
141:                     idfv = m_NativeStore.FetchVendorIdentifier();
142:                     if (adsIntentGranted)
143:                     {
144:                         m_FirebaseAnalyticsClient ??= new AppleFirebaseAnalyticsClient();
145:                         (appInstanceId, firebaseSessionId, firebaseAppId) = await FetchEnabledFirebaseIdsAsync(m_FirebaseAnalyticsClient);
146:                     }
147:                     break;
148:             }
149: 
150: 
151:             return new PlayerIdentity(
152:                 unityImpressionId: impressionId,
153:                 unityInstallationId: m_CoreRegistry.InstallationId,
154:                 sessionId: m_SessionId,
155:                 unityAnalyticsId: m_AnalyticsId,
156:                 unityIdfa: idfa,
157:                 unityIdfv: idfv,
158:                 unityGaid: gaid,
159:                 unityAppInstanceId: appInstanceId,
160:                 unityFirebaseSessionId: firebaseSessionId,
161:                 unityFirebaseAppId: firebaseAppId,
162:                 unityIapSdkVersion: IAPVersion.Current,
163:                 unityEngineVersion: m_Util.unityVersion,
164:                 unityApplicationVersion: m_Util.gameVersion,
165:                 unityUserId: m_CoreRegistry.ExternalUserId,
166:                 unityInstallationTimestamp: AppInstallInfo.GetInstallTimestamp() ?? default
167: #if ENABLE_UNITY_CONSENT
168:                 , unityConsentStateAdsIntent: ConsentStateAdsIntent
169:                 , unityConsentStateAnalyticsIntent: ConsentStateAnalyticsIntent
170: #endif
171:             );
172:         }

176:         internal async Task<(string? appInstanceId, string? firebaseSessionId, string? firebaseAppId)> FetchEnabledFirebaseIdsAsync(IFirebaseAnalyticsClient client)
177:         {
178:             var enabledAttributes = EnabledAttributes;
179:             string? appInstanceId = null;
180:             string? firebaseSessionId = null;
181:             string? firebaseAppId = null;
182:             // Google Analytics seems to bind its ids at configure: before it, the app id is the plist fallback, the app
183:             // instance id can still be reset, and the session id is always null. Ids are cached only once configured,
184:             // as Google Analytics seems to keep the first configured app's ids until relaunch (observed with Firebase
185:             // iOS SDK 10.29 and 12.19). Android has no configure step.
186:             var defaultAppConfigured = !(client is IFirebaseDefaultAppState state) || state.IsDefaultAppConfigured;
187:             if (enabledAttributes.Contains(ConnectionsSettingsClient.AppInstanceIdKey))
188:             {
189:                 appInstanceId = m_CachedAppInstanceId ?? await client.FetchAppInstanceIdAsync();
190:                 if (defaultAppConfigured)
191:                 {
192:                     m_CachedAppInstanceId ??= appInstanceId;
193:                 }
194:             }
195:             // Not requested before configure, where it is always null.
196:             if (enabledAttributes.Contains(ConnectionsSettingsClient.FirebaseSessionIdKey) && defaultAppConfigured && !m_FirebaseSessionIdTimedOut)
197:             {
198:                 if (m_CachedFirebaseSessionId == null)
199:                 {
200:                     var (sessionId, timedOut) = await client.FetchSessionIdAsync();
201:                     m_CachedFirebaseSessionId = sessionId;
202:                     // A null session id that hit the native timeout is cached, so later identities skip the 2 s wait.
203:                     m_FirebaseSessionIdTimedOut = (sessionId == null) && timedOut;
204:                 }
205:                 firebaseSessionId = m_CachedFirebaseSessionId;
206:             }
207:             if (enabledAttributes.Contains(ConnectionsSettingsClient.FirebaseAppIdKey))
208:             {
209:                 firebaseAppId = m_CachedFirebaseAppId ?? await client.FetchAppIdAsync();
210:                 if (defaultAppConfigured)
211:                 {
212:                     m_CachedFirebaseAppId ??= firebaseAppId;
213:                 }
214:             }
215:             return (appInstanceId, firebaseSessionId, firebaseAppId);
216:         }
217: 
218:         // Which Google Analytics identifiers the project allows collecting,
219:         // per remote connections settings. Non-blocking: empty (collect
220:         // nothing) until the session's background fetch has succeeded, so
221:         // identity creation never waits on the network.
222:         HashSet<string> EnabledAttributes
223:         {
224:             get
225:             {
226:                 m_ConnectionsSettingsClient ??= new ConnectionsSettingsClient(m_CoreRegistry);
227:                 return m_ConnectionsSettingsClient.CachedEnabledAttributes;
228:             }
229:         }

