103:         // Overridable for tests; returns null on any failure (never throws).
104:         protected virtual async Task<HashSet<string>?> FetchEnabledAttributesAsync()
105:         {
106:             try
107:             {
108:                 var projectId = m_CoreRegistry.CloudProjectId;
109:                 var installationId = m_CoreRegistry.InstallationId;
110:                 if (string.IsNullOrEmpty(projectId) || string.IsNullOrEmpty(installationId))
111:                 {
112:                     return null;
113:                 }
114: 
115:                 var body = MiniJson.JsonEncode(new Dictionary<string, object>
116:                 {
117:                     ["projectId"] = projectId!,
118:                     ["installationId"] = installationId!,
119:                     ["platform"] = Application.platform.ToString(),
120:                     ["appVersion"] = Application.version,
121:                     ["editorVersion"] = Application.unityVersion,
122:                     ["sdkVersion"] = IAPVersion.Current
123:                 });
124: 
125:                 var response = await PostAsync(ResolveHost() + k_Path, body);
126:                 return response == null ? null : ParseEnabledAttributes(response);
127:             }
128:             catch (Exception e)
129:             {
130:                 Debug.unityLogger.LogIAPVerbose($"get-connections-settings fetch failed: {e.Message}");
131:                 return null;
132:             }
133:         }
